    private fun vectors(): JSONArray {
        // Walk up out of the module to the fixtures shared with iOS.
        var dir = File(System.getProperty("user.dir") ?: ".").absoluteFile
        var fixture: File? = null
        repeat(8) {
            val candidate = File(dir, "sdk/native/fixtures/replay-vectors.json")
            if (candidate.exists()) {
                fixture = candidate
                return@repeat
            }
            dir = dir.parentFile ?: dir
        }
        // Not a skip. A missing fixture means the cross-language gate
